85	// Render a path for messages only.
86	//
87	// A plain name -- valid UTF-8 with no ASCII control byte, no double quote,
88	// and no backslash -- is shown verbatim, exactly as before. Anything else is
89	// wrapped in double quotes and rendered with escapes:
90	//
91	//   \n \r \t   newline, carriage return, tab (so a name can never break a
92	//              message across lines or smuggle terminal control bytes in)
93	//   \"  \\     double quote and backslash
94	//   \xhh       every other ASCII control byte, and every raw byte that is
95	//              not part of valid UTF-8, as two lowercase hex digits
96	//
97	// Decodable non-ASCII text (e.g. Chinese characters) is kept as-is inside
98	// the quotes. The result therefore never contains a raw ASCII control byte
99	// (the line terminator printed after the message is the only one), and two
100	// different raw names always render differently: a real 0xff byte shows as
101	// `\xff` while a name literally containing those four characters shows as
102	// `\\xff`, and a real newline shows as `\n` while a backslash followed by
103	// `n` shows as `\\n`.
104	//
105	// This string is purely informational -- it is never used to create, look
106	// up, or remove anything. The original OsStr is used for every filesystem
107	// operation, so non-UTF-8 names are still operated on byte for byte.
108	#[cfg(unix)]
109	fn render_path(path: &OsStr) -> String {
110	    const QUOTE: u8 = b'"';
111	    const BACKSLASH: u8 = b'\\';
112	
113	    let bytes = path.as_encoded_bytes();
114	
115	    // Valid UTF-8 with nothing that needs an escape: keep the historical
116	    // bare display (and the bare "Key saved to ..." wording).
117	    if std::str::from_utf8(bytes).is_ok()
118	        && bytes
119	            .iter()
120	            .all(|&b| b >= 0x20 && b != QUOTE && b != BACKSLASH && b != 0x7f)
121	    {
122	        return String::from_utf8(bytes.to_vec()).unwrap();
123	    }
124	
125	    let mut out = String::with_capacity(bytes.len() + 2);
126	    out.push('"');
127	
128	    // Walk the raw bytes, stepping over whole UTF-8 sequences so a valid
129	    // multi-byte character is shown intact while an undecodable byte is
130	    // escaped on its own.
131	    let mut i = 0;
132	    while i < bytes.len() {
133	        let b = bytes[i];
134	
135	        if b < 0x80 {
136	            match b {
137	                b'\n' => out.push_str("\\n"),
138	                b'\r' => out.push_str("\\r"),
139	                b'\t' => out.push_str("\\t"),
140	                QUOTE => out.push_str("\\\""),
141	                BACKSLASH => out.push_str("\\\\"),
142	                // Printable ASCII (0x20..=0x7e except the two handled above)
143	                // is shown as itself.
144	                0x20..=0x7e => out.push(b as char),
145	                // Every remaining ASCII control byte (including NUL and
146	                // DEL) is rendered explicitly.
147	                _ => out.push_str(&format!("\\x{b:02x}")),
148	            }
149	            i += 1;
150	            continue;
151	        }
152	
153	        // Length of the UTF-8 sequence starting here.
154	        let seq_len = if b & 0xe0 == 0xc0 {
155	            2
156	        } else if b & 0xf0 == 0xe0 {
157	            3
158	        } else if b & 0xf8 == 0xf0 {
159	            4
160	        } else {
161	            // 0x80..0xbf continuation byte, or 0xf8..0xff lead: never legal
162	            // here.
163	            1
164	        };
165	
166	        if seq_len > 1
167	            && i + seq_len <= bytes.len()
168	            && std::str::from_utf8(&bytes[i..i + seq_len]).is_ok()
169	        {
170	            // from_utf8 on a maximal, well-formed sequence succeeds; push the
171	            // character as text so e.g. Chinese names keep their glyphs.
172	            out.push_str(std::str::from_utf8(&bytes[i..i + seq_len]).unwrap());
173	            i += seq_len;
174	        } else {
175	            out.push_str(&format!("\\x{b:02x}"));
176	            i += 1;
177	        }
178	    }
179	
180	    out.push('"');
181	    out
182	}
