422	/// Overwrite a secret-holding buffer with zeroes in a way the compiler must
423	/// keep.
424	///
425	/// A plain `buf.fill(0)` at the end of a key's lifetime is not enough: once
426	/// the buffer is never read again, an optimizing compiler is free to delete
427	/// those stores as dead code, so under an optimized build the secret bytes
428	/// would stay on the stack. Every byte here is written through
429	/// `write_volatile`, which the optimizer must emit regardless of later
430	/// reads -- the same guarantee libc's `explicit_bzero(3)` gives -- so the
431	/// erasure does not depend on the optimization level. It is implemented
432	/// directly rather than calling a libc symbol so the protection also holds
433	/// on Unix targets whose libc does not provide `explicit_bzero`.
434	///
435	/// Call this for every buffer that directly holds (any prefix of) the
436	/// generated key, on both success and every error path.
437	#[cfg(unix)]
438	fn secure_zero(buf: &mut [u8]) {
439	    let base = buf.as_mut_ptr();
440	    for offset in 0..buf.len() {
441	        // SAFETY: `offset` is in bounds of `buf`, a live allocation
442	        // exclusively borrowed for this whole call; `u8` imposes no
443	        // initialization invariant and has no drop glue.
444	        unsafe {
445	            std::ptr::write_volatile(base.add(offset), 0u8);
446	        }
447	    }
448	}
