1	//! Regression coverage for the temporary key's in-memory lifecycle on Unix:
2	//! the 32 bytes the OS random source delivers are held directly in one
3	//! stack buffer while the key is saved, and that whole buffer is overwritten
4	//! with zeroes *before the keygen operation returns* -- under both the
5	//! unoptimized and the optimized (release) build.
6	//!
7	//! Why this needs more than the existing tests
8	//! --------------------------------------------
9	//! File deletion, an empty stdout/stderr, and a 0/1 exit code cannot prove
10	//! the wipe happened: the whole process image vanishes on exit, and even a
11	//! still-secret stack slot could be overwritten later by an unrelated frame.
12	//! The promise in README ("内存中的临时密钥清零") is about the buffer that
13	//! directly held the random bytes while the operation was in flight, so the
14	//! buffer has to be inspected *during* the run:
15	//!
16	//!   * that non-zero secret bytes really were delivered and really were
17	//!     held through the save (the saved file must still be that exact key,
18	//!     not zeroes and not truncated);
19	//!   * and that those bytes were all overwritten before the operation
20	//!     returned (in particular before its stdout/stderr report).
21	//!
22	//! The tests drive the real wrapfile binary under
23	//! `tests/support/keylife/keylife`, an *external* ptrace observer (not an
24	//! LD_PRELOAD shim): it forks, its child PTRACE_TRACEME's itself and execs
25	//! wrapfile, and the observer locates the 32-byte buffer at the getrandom
26	//! syscall, reads it across the file operations, and single-steps the guest
27	//! after the save (success -- including a close that merely reports EINTR),
28	//! after the emulated random-source failure, after a mid-save write failure,
29	//! and after an unrecoverable close error (with the cleanup both allowed
30	//! and refused) to watch the whole buffer become zero before the first
31	//! stdout/stderr write. For a partial-draw failure it also plants a
32	//! non-zero sentinel in the slots the random source never delivered (those
33	//! slots stay zero from initialization), so a wipe covering only the
34	//! delivered prefix is caught too.
35	//!
36	//! The random source is made deterministic and fail-able by the existing
37	//! randtrap shim (fixed 0x80.. byte pattern; seccomp SIGSYS emulation), and
38	//! the write failure by the existing permfail shim. Nothing in the product
39	//! changes.
40	//!
41	//! Every scenario is run against the debug binary (`CARGO_BIN_EXE_wrapfile`)
42	//! and a freshly built `--release` binary, since an optimizer deleting a
43	//! dead plain `fill(0)` is precisely one of the regressions this guards.
44	#![cfg(unix)]
45	
46	mod common;
47	
48	use std::collections::HashMap;
49	use std::fs;
50	use std::os::unix::fs::{MetadataExt, PermissionsExt};
51	use std::path::{Path, PathBuf};
52	use std::process::Command;
53	use std::sync::atomic::{AtomicU64, Ordering};
54	
55	const KEY_LEN: usize = 32;
56	const MODE_0600: u32 = 0o600;
57	
58	// ---------------------------------------------------------------------------
59	// binaries: the profile under which `cargo test` runs, plus a release build
60	// ---------------------------------------------------------------------------
61	
62	fn debug_bin() -> PathBuf {
63	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
64	}
65	
66	/// Ensure a release/optimized wrapfile is available and return its path.
67	/// `None` (reason printed) if one cannot be produced here, so the release
68	/// cases skip instead of failing.
69	///
70	/// When the tests themselves run under `cargo test --release`, the test
71	/// binary already lives in target/release and that wrapfile is reused.
72	/// Otherwise a release wrapfile is built into a *separate* target
73	/// directory under CARGO_TARGET_TMPDIR: running `cargo build` against the
74	/// main target dir from inside a test would block on Cargo's target lock
75	/// for as long as the whole test process runs (a self-deadlock).
76	fn release_bin() -> Option<PathBuf> {
77	    static READY: std::sync::OnceLock<Option<PathBuf>> = std::sync::OnceLock::new();
78	    READY.get_or_init(|| {
79	        let debug = debug_bin();
80	        if debug
81	            .components()
82	            .any(|c| c.as_os_str() == "release")
83	        {
84	            return Some(debug);
85	        }
86	
87	        let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
88	        let scratch = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
89	            .join("wrapfile-release-for-zeroing-tests");
90	        let _ = fs::create_dir_all(&scratch);
91	        let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
92	        let status = Command::new(&cargo)
93	            .args(["build", "--release", "--offline", "--quiet"])
94	            .current_dir(&manifest)
95	            .env("CARGO_TARGET_DIR", &scratch)
96	            .status();
97	        let path = scratch.join("release").join("wrapfile");
98	        match status {
99	            Ok(s) if s.success() && path.is_file() => Some(path),
100	            Ok(s) => {
101	                eprintln!(
102	                    "skipping release-profile zeroing cases: building the \
103	                     release guest exited with {s}"
104	                );
105	                None
106	            }
107	            Err(e) => {
108	                eprintln!(
109	                    "skipping release-profile zeroing cases: cannot run \
110	                     `{cargo}` to build the release guest: {e}"
111	                );
112	                None
113	            }
114	        }
115	    })
116	    .clone()
117	}
118	
119	// ---------------------------------------------------------------------------
120	// scratch directory
121	// ---------------------------------------------------------------------------
122	
123	struct Tmp {
124	    path: PathBuf,
125	}
126	
127	impl Tmp {
128	    fn new(label: &str) -> Tmp {
129	        static SEQ: AtomicU64 = AtomicU64::new(0);
130	        let path = std::env::temp_dir().join(format!(
131	            "wrapfile-keygen-zeroing-tests-{}-{}-{}",
132	            std::process::id(),
133	            label,
134	            SEQ.fetch_add(1, Ordering::Relaxed)
135	        ));
136	        fs::create_dir_all(&path).unwrap();
137	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
138	        Tmp { path }
139	    }
140	
141	    fn child(&self, name: &str) -> PathBuf {
142	        self.path.join(name)
143	    }
144	}
145	
146	impl Drop for Tmp {
147	    fn drop(&mut self) {
148	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
149	        let _ = fs::remove_dir_all(&self.path);
150	    }
151	}
152	
153	// ---------------------------------------------------------------------------
154	// observer event stream
155	// ---------------------------------------------------------------------------
156	
157	#[derive(Debug, Clone)]
158	struct Event {
159	    name: String,
160	    attrs: HashMap<String, String>,
161	}
162	
163	impl Event {
164	    fn get(&self, key: &str) -> Option<&str> {
165	        self.attrs.get(key).map(String::as_str)
166	    }
167	    fn usize(&self, key: &str) -> Option<usize> {
168	        self.get(key).and_then(|v| v.parse().ok())
169	    }
170	    fn i64(&self, key: &str) -> Option<i64> {
171	        self.get(key).and_then(|v| v.parse().ok())
172	    }
173	}
174	
175	struct Observation {
176	    rc: i32,
177	    observer_err: String,
178	    events: Vec<Event>,
179	    fail: Option<String>,
180	}
181	
182	impl Observation {
183	    fn named(&self, name: &str) -> Vec<&Event> {
184	        self.events.iter().filter(|e| e.name == name).collect()
185	    }
186	    fn first(&self, name: &str) -> Option<&Event> {
187	        self.events.iter().find(|e| e.name == name)
188	    }
189	    fn index(&self, name: &str) -> Option<usize> {
190	        self.events.iter().position(|e| e.name == name)
191	    }
192	    fn secret(&self) -> Vec<u8> {
193	        let hex = self
194	            .first("FILL_COMPLETE")
195	            .and_then(|e| e.get("secret"))
196	            .expect("FILL_COMPLETE secret=");
197	        assert_eq!(hex.len() % 2, 0);
198	        (0..hex.len() / 2)
199	            .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
200	            .collect()
201	    }
202	}
203	
204	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
205	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
206	}
207	
208	fn parse_events(stdout: &[u8]) -> Vec<Event> {
209	    String::from_utf8_lossy(stdout)
210	        .lines()
211	        .filter_map(|line| {
212	            let mut it = line.split_whitespace();
213	            let tag = it.next()?;
214	            if tag != "EVENT" {
215	                return None;
216	            }
217	            let mut attrs = HashMap::new();
218	            let mut name = String::new();
219	            for kv in it {
220	                let (k, v) = kv.split_once('=')?;
221	                if k == "name" {
222	                    name = v.to_string();
223	                } else {
224	                    attrs.insert(k.to_string(), v.to_string());
225	                }
226	            }
227	            (!name.is_empty()).then_some(Event { name, attrs })
228	        })
229	        .collect()
230	}
231	
232	fn fail_reason(stdout: &[u8]) -> Option<String> {
233	    String::from_utf8_lossy(stdout)
234	        .lines()
235	        .find_map(|l| l.strip_prefix("FAIL reason=").map(str::to_string))
236	}
237	
238	/// Run the keylife observer around `wrapfile keygen <key>` with the given
239	/// LD_PRELOAD libraries and extra environment.
240	fn observe(
241	    observer: &Path,
242	    bin: &Path,
243	    scenario: &str,
244	    key: &Path,
245	    preloads: &[PathBuf],
246	    extra_env: &[(&str, &str)],
247	    trace: &Path,
248	) -> Observation {
249	    let dir = key.parent().unwrap();
250	    let out_cap = dir.join("guest.stdout");
251	    let err_cap = dir.join("guest.stderr");
252	    for f in [&out_cap, &err_cap] {
253	        let _ = fs::remove_file(f);
254	    }
255	
256	    let preload = preloads
257	        .iter()
258	        .map(|p| p.display().to_string())
259	        .collect::<Vec<_>>()
260	        .join(":");
261	
262	    let output = Command::new(observer)
263	        .arg(scenario)
264	        .arg(&out_cap)
265	        .arg(&err_cap)
266	        .arg("--")
267	        .arg(bin)
268	        .arg("keygen")
269	        .arg(key)
270	        .env("LD_PRELOAD", preload)
271	        .env("WRAPFILE_TEST_TRACE_FILE", trace)
272	        .envs(extra_env.iter().copied())
273	        .output()
274	        .expect("run keylife observer");
275	
276	    Observation {
277	        rc: output.status.code().unwrap_or(-1),
278	        observer_err: String::from_utf8_lossy(&output.stderr).into_owned(),
279	        events: parse_events(&output.stdout),
280	        fail: fail_reason(&output.stdout),
281	    }
282	}
283	
284	fn guest_captured(key: &Path) -> (Vec<u8>, Vec<u8>) {
285	    let dir = key.parent().unwrap();
286	    let out = fs::read(dir.join("guest.stdout")).unwrap_or_default();
287	    let err = fs::read(dir.join("guest.stderr")).unwrap_or_default();
288	    (out, err)
289	}
290	
291	// ---------------------------------------------------------------------------
292	// shim / observer availability
293	// ---------------------------------------------------------------------------
294	
295	struct Support {
296	    observer: PathBuf,
297	    randtrap: PathBuf,
298	    permfail: PathBuf,
299	}
300	
301	fn support() -> Option<Support> {
302	    let observer = common::keylife_bin()?;
303	    let randtrap = common::randtrap_so()?;
304	    let permfail = common::permfail_so()?;
305	    Some(Support { observer, randtrap, permfail })
306	}
307	
308	/// True when the randtrap shim armed its seccomp trap in the guest (a
309	/// machine without seccomp must skip, not fail).
310	fn trap_armed(trace: &Path) -> bool {
311	    match fs::read_to_string(trace) {
312	        Ok(t) => t.lines().any(|l| l == "TRAP armed"),
313	        Err(_) => false,
314	    }
315	}
316	
317	// ---------------------------------------------------------------------------
318	// randtrap trace helpers
319	// ---------------------------------------------------------------------------
320	
321	#[derive(Debug)]
322	struct GrEvent {
323	    req: usize,
324	    base: usize,
325	    ret: i64,
326	}
327	
328	fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
329	    let text = fs::read_to_string(trace).unwrap();
330	    text.lines()
331	        .filter_map(|line| {
332	            let mut parts = line.split_whitespace();
333	            if parts.next() != Some("GETRANDOM") {
334	                return None;
335	            }
336	            let mut req = None;
337	            let mut base = None;
338	            let mut ret = None;
339	            for kv in parts {
340	                let (k, v) = kv.split_once('=')?;
341	                match k {
342	                    "req" => req = v.parse().ok(),
343	                    "base" => base = v.parse().ok(),
344	                    "ret" => ret = v.parse().ok(),
345	                    _ => {}
346	                }
347	            }
348	            Some(GrEvent { req: req?, base: base?, ret: ret? })
349	        })
350	        .collect()
351	}
352	
353	fn pattern_byte(i: usize) -> u8 {
354	    (0x80 + (i % 64)) as u8
355	}
356	
357	/// The random bytes the key fill received, reconstructed from the trace.
358	fn key_fill_bytes(events: &[GrEvent]) -> Vec<u8> {
359	    let start = events
360	        .iter()
361	        .rposition(|e| e.req == KEY_LEN)
362	        .expect("keygen must draw the 32 key bytes");
363	    events[start..]
364	        .iter()
365	        .filter(|e| e.ret > 0)
366	        .flat_map(|e| (0..e.ret as usize).map(move |i| pattern_byte(e.base + i)))
367	        .collect()
368	}
369	
370	/// Global draw index at which keygen's own 32-byte fill starts: the `base`
371	/// of its first (req=32) call. Bytes before that are the process runtime's
372	/// own startup consumption and vary across environments, so a fail-after-N
373	/// scenario is calibrated from this instead of a hard-coded N.
374	fn key_fill_base(events: &[GrEvent]) -> usize {
375	    events
376	        .iter()
377	        .rposition(|e| e.req == KEY_LEN)
378	        .map(|i| events[i].base)
379	        .expect("keygen must draw the 32 key bytes")
380	}
381	
382	// ---------------------------------------------------------------------------
383	// permfail shim trace (its lines share the trace file with randtrap's)
384	// ---------------------------------------------------------------------------
385	
386	struct ShimEvent {
387	    kind: String,
388	    attrs: HashMap<String, String>,
389	}
390	
391	impl ShimEvent {
392	    fn get(&self, key: &str) -> Option<&str> {
393	        self.attrs.get(key).map(String::as_str)
394	    }
395	}
396	
397	fn shim_events(trace: &Path) -> Vec<ShimEvent> {
398	    fs::read_to_string(trace)
399	        .unwrap()
400	        .lines()
401	        .map(|line| {
402	            let mut it = line.split_whitespace();
403	            let kind = it.next().unwrap_or("").to_string();
404	            let attrs = it
405	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
406	                .collect();
407	            ShimEvent { kind, attrs }
408	        })
409	        .collect()
410	}
411	
412	fn shim_event_seen(events: &[ShimEvent], kind: &str, key: &str, value: &str) -> bool {
413	    events
414	        .iter()
415	        .any(|e| e.kind == kind && e.get(key) == Some(value))
416	}
417	
418	/// The bytes the key file's write() calls landed, reconstructed from the
419	/// shim's TRACE_BYTES hex in call order.
420	fn landed_bytes(events: &[ShimEvent]) -> Vec<u8> {
421	    events
422	        .iter()
423	        .filter(|e| e.kind == "WRITE")
424	        .filter_map(|e| e.get("hex"))
425	        .flat_map(|hex| {
426	            assert_eq!(hex.len() % 2, 0, "odd hex in trace line");
427	            (0..hex.len() / 2)
428	                .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
429	                .collect::<Vec<u8>>()
430	        })
431	        .collect()
432	}
433	
434	// ---------------------------------------------------------------------------
435	// filesystem helpers
436	// ---------------------------------------------------------------------------
437	
438	fn mode_of(path: &Path) -> u32 {
439	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
440	}
441	
442	fn make_sibling(dir: &Path) -> (PathBuf, Vec<u8>, u32) {
443	    let p = dir.join("sibling");
444	    let bytes: Vec<u8> = (0..32).map(|i| b'a' + (i % 26) as u8).collect();
445	    fs::write(&p, &bytes).unwrap();
446	    fs::set_permissions(&p, fs::Permissions::from_mode(0o640)).unwrap();
447	    (p, bytes, 0o640)
448	}
449	
450	fn assert_sentinel_untouched(path: &Path, bytes: &[u8], mode: u32) {
451	    let meta = fs::metadata(path).unwrap();
452	    assert_eq!(meta.mode() & 0o7777, mode, "sibling permissions changed");
453	    assert_eq!(fs::read(path).unwrap(), bytes, "sibling contents changed");
454	}
455	
456	/// Key material must not surface on stdout/stderr in any encoding: not as
457	/// raw bytes, and not as a hex rendering.
458	fn assert_key_not_leaked(out: &[u8], err: &[u8], secret: &[u8]) {
459	    assert!(
460	        !contains_slice(out, secret) && !contains_slice(err, secret),
461	        "the key must never appear on stdout/stderr as raw bytes"
462	    );
463	    let hex: String = secret.iter().map(|b| format!("{b:02x}")).collect();
464	    let out_text = String::from_utf8_lossy(out);
465	    let err_text = String::from_utf8_lossy(err);
466	    assert!(
467	        !out_text.contains(&hex) && !err_text.contains(&hex),
468	        "the key must never appear on stdout/stderr in hex form"
469	    );
470	}
471	
472	// Every scenario needs the observer to run successfully (rc 0) and reach a
473	// guest exit. rc 2 means the observer itself could not run in this
474	// environment (e.g. ptrace forbidden): the caller skips.
475	fn observer_ran(obs: &Observation) -> bool {
476	    if obs.rc == 2 {
477	        eprintln!(
478	            "skipping: keylife observer could not run here: {}",
479	            obs.observer_err.trim()
480	        );
481	        false
482	    } else {
483	        true
484	    }
485	}
486	
487	// ---------------------------------------------------------------------------
488	// scenarios, parameterized by the guest binary (debug / release)
489	// ---------------------------------------------------------------------------
490	
491	fn success_wipes_full_key_and_saves_it_intact(sup: &Support, bin: &Path, profile: &str) {
492	    let tmp = Tmp::new(&format!("success-{profile}"));
493	    let key = tmp.child("key");
494	    let trace = tmp.child("trace.log");
495	    fs::File::create(&trace).unwrap();
496	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
497	
498	    // Short, always-successful reads from the deterministic source: not a
499	    // failure, and every delivered byte is recognisable in memory/file.
500	    let obs = observe(
501	        &sup.observer,
502	        bin,
503	        "success",
504	        &key,
505	        &[sup.randtrap.clone()],
506	        &[("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8")],
507	        &trace,
508	    );
509	    if !observer_ran(&obs) {
510	        return;
511	    }
512	    if !trap_armed(&trace) {
513	        eprintln!("skipping: randtrap seccomp trap did not arm here");
514	        return;
515	    }
516	    assert_eq!(
517	        obs.rc, 0,
518	        "[{profile}] observer must report success, got FAIL: {:?}",
519	        obs.fail.clone()
520	    );
521	
522	    // (1) Non-zero secret really was delivered into the one buffer...
523	    let fill = obs
524	        .first("FILL_COMPLETE")
525	        .expect("FILL_COMPLETE event");
526	    assert_eq!(fill.usize("held"), Some(KEY_LEN));
527	    let secret = obs.secret();
528	    assert_eq!(secret.len(), KEY_LEN);
529	    assert!(
530	        secret.iter().all(|&b| b != 0),
531	        "the held key must consist of non-zero delivered bytes"
532	    );
533	    // ...and matches what the random source actually handed keygen.
534	    let delivered = key_fill_bytes(&getrandom_events(&trace));
535	    assert_eq!(delivered.len(), KEY_LEN);
536	    assert_eq!(secret, delivered, "observed buffer bytes must equal delivery");
537	
538	    // (2) The same live bytes were borrowed for the save (never zeroed
539	    // before/during), and were still present when close returned.
540	    assert!(!obs.named("WRITE_BORROWS").is_empty(), "key writes must be seen");
541	    assert!(obs.first("CLOSE_STILL_HELD").is_some());
542	
543	    // (3) The whole 32-byte buffer was zeroed in a tight local loop before
544	    // the first stdout/stderr write -- and before the operation returned.
545	    let wiped = obs.first("WIPED").expect("WIPED event");
546	    assert_eq!(wiped.usize("held"), Some(KEY_LEN));
547	    assert_eq!(wiped.usize("sentinel"), Some(0));
548	    let steps = wiped.i64("steps").expect("WIPED steps=");
549	    assert!(
550	        (1..1_000_000).contains(&steps),
551	        "wipe must be a small bounded local loop, got {steps} steps"
552	    );
553	    let i_wiped = obs.index("WIPED").unwrap();
554	    let i_output = obs
555	        .index("OUTPUT_AFTER_WIPE")
556	        .expect("a post-wipe stdout/stderr write must be seen");
557	    let i_close = obs.index("CLOSE_STILL_HELD").unwrap();
558	    assert!(i_close < i_wiped, "wipe must follow the save's close");
559	    assert!(i_wiped < i_output, "wipe must precede the success report");
560	
561	    let guest_exit = obs
562	        .first("GUEST_EXIT")
563	        .and_then(|e| e.i64("rc"))
564	        .expect("guest exit event");
565	    assert_eq!(guest_exit, 0);
566	
567	    // Public behavior is unchanged: exactly the delivered 32 bytes, mode
568	    // exactly 0600, stdout only the save-location line, stderr empty.
569	    let on_disk = fs::read(&key).expect("key file must exist");
570	    assert_eq!(on_disk.len(), KEY_LEN);
571	    assert_eq!(on_disk, secret, "the saved key must be the delivered bytes");
572	    assert_eq!(mode_of(&key), MODE_0600, "key file mode must be exactly 0600");
573	
574	    let (out, err) = guest_captured(&key);
575	    assert!(err.is_empty(), "stderr must be empty on success: {err:?}");
576	    assert_eq!(
577	        out,
578	        format!("Key saved to {}\n", key.display()).into_bytes()
579	    );
580	}
