831	/// Shared observer-side assertions for the two close-failure scenarios:
832	/// the full non-zero key was delivered and borrowed through the save, the
833	/// injected close fault really fired after a complete synced write, and the
834	/// whole buffer was wiped in a tight local loop after the failed close and
835	/// before the first failure-report byte.
836	fn assert_closefail_wipe(obs: &Observation, trace: &Path, profile: &str) -> Vec<u8> {
837	    assert_eq!(
838	        obs.rc, 0,
839	        "[{profile}] observer must confirm the wipe, got FAIL: {:?}",
840	        obs.fail.clone()
841	    );
842	
843	    // The full, non-zero key really was delivered and is what the save
844	    // borrowed (never zeroed before or during the writes).
845	    let secret = obs.secret();
846	    assert_eq!(secret.len(), KEY_LEN);
847	    assert!(secret.iter().all(|&b| b != 0));
848	    let delivered = key_fill_bytes(&getrandom_events(trace));
849	    assert_eq!(delivered.len(), KEY_LEN);
850	    assert_eq!(secret, delivered, "observed buffer bytes must equal delivery");
851	    assert!(!obs.named("WRITE_BORROWS").is_empty(), "key writes must be seen");
852	
853	    // The fault really was injected: all 32 bytes landed and were synced,
854	    // then close reported EIO (the descriptor was really released).
855	    let shim = shim_events(trace);
856	    assert!(
857	        shim_event_seen(&shim, "FSYNC", "ret", "0"),
858	        "the key must have been fully synced before the close"
859	    );
860	    assert!(
861	        shim_event_seen(&shim, "CLOSE", "errno", "EIO"),
862	        "the unrecoverable close error must have been injected"
863	    );
864	    assert_eq!(
865	        landed_bytes(&shim),
866	        secret,
867	        "the bytes that landed on disk are exactly the delivered key"
868	    );
869	
870	    // The key was still held when the close returned; the whole buffer was
871	    // then wiped before the failure report and before the operation
872	    // returned.
873	    assert!(
874	        obs.first("CLOSE_STILL_HELD").is_some(),
875	        "the full key must still be held when the failed close returns"
876	    );
877	    let wiped = obs.first("WIPED").expect("WIPED event");
878	    assert_eq!(wiped.usize("held"), Some(KEY_LEN));
879	    assert_eq!(wiped.usize("sentinel"), Some(0));
880	    let steps = wiped.i64("steps").expect("WIPED steps=");
881	    assert!(
882	        (1..1_000_000).contains(&steps),
883	        "wipe must be a small bounded local loop, got {steps} steps"
884	    );
885	    let i_close = obs.index("CLOSE_STILL_HELD").unwrap();
886	    let i_wiped = obs.index("WIPED").unwrap();
887	    let i_output = obs
888	        .index("OUTPUT_AFTER_WIPE")
889	        .expect("the failure report must be observed after the wipe");
890	    assert!(i_close < i_wiped, "wipe must follow the failed close");
891	    assert!(i_wiped < i_output, "wipe must precede the failure report");
892	    assert_eq!(
893	        obs.first("GUEST_EXIT").and_then(|e| e.i64("rc")),
894	        Some(1),
895	        "an unrecoverable close error must fail the save"
896	    );
897	
898	    secret
899	}
