973	fn close_failure_with_unlink_refused_still_wipes_the_full_key(
974	    sup: &Support,
975	    bin: &Path,
976	    profile: &str,
977	) {
978	    let tmp = Tmp::new(&format!("closefail-unlink-refused-{profile}"));
979	    let key = tmp.child("key");
980	    let (sib, sib_bytes, sib_mode) = make_sibling(&tmp.path);
981	    let parent_before = mode_of(&tmp.path);
982	    let trace = tmp.child("trace.log");
983	    fs::File::create(&trace).unwrap();
984	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
985	
986	    // Same unrecoverable close error, but the system also refuses to remove
987	    // this run's file (the shim's unlink fails with EACCES without any
988	    // syscall). The same in-memory wipe contract must hold, and the report
989	    // must keep the close failure while warning about the residue.
990	    let obs = observe(
991	        &sup.observer,
992	        bin,
993	        "closefail",
994	        &key,
995	        &[sup.randtrap.clone(), sup.permfail.clone()],
996	        &[
997	            ("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8"),
998	            ("WRAPFILE_TEST_FAIL_CLOSE", "1"),
999	            ("WRAPFILE_TEST_FAIL_UNLINK", "1"),
1000	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
1001	        ],
1002	        &trace,
1003	    );
1004	    if !observer_ran(&obs) {
1005	        return;
1006	    }
1007	    if !trap_armed(&trace) {
1008	        eprintln!("skipping: randtrap seccomp trap did not arm here");
1009	        return;
1010	    }
1011	    let secret = assert_closefail_wipe(&obs, &trace, profile);
1012	
1013	    // The refused cleanup really was injected, in user space: no unlinkat
1014	    // syscall ever reached the kernel, so the observer saw no ABORT_UNLINK.
1015	    let shim = shim_events(&trace);
1016	    assert!(
1017	        shim_event_seen(&shim, "UNLINK", "errno", "EACCES"),
1018	        "the refused cleanup must have been injected"
1019	    );
1020	    assert!(
1021	        obs.first("ABORT_UNLINK").is_none(),
1022	        "a refused unlink performs no syscall the observer could see"
1023	    );
1024	
1025	    // Public failure behavior: exit 1, empty stdout; stderr keeps the close
1026	    // failure, reports the unfinished cleanup, and warns that this run's
1027	    // file may remain -- never that it is gone, never a success.
1028	    let (out, err) = guest_captured(&key);
1029	    assert!(out.is_empty(), "no success message on failure");
1030	    let err_text = String::from_utf8_lossy(&err);
1031	    assert!(
1032	        err_text.contains("closing the key file"),
1033	        "stderr must keep the close failure reason: {err_text}"
1034	    );
1035	    assert!(
1036	        err_text.contains(&key.display().to_string()),
1037	        "stderr must name the target: {err_text}"
1038	    );
1039	    assert!(
1040	        err_text.contains("cleanup"),
1041	        "stderr must report the failed cleanup: {err_text}"
1042	    );
1043	    assert!(
1044	        err_text.contains("may still be present"),
1045	        "stderr must warn that this run's file may remain: {err_text}"
1046	    );
1047	    assert!(
1048	        !err_text.contains("Key saved to"),
1049	        "the residue must not be reported as a saved key: {err_text}"
1050	    );
1051	    assert_key_not_leaked(&out, &err, &secret);
1052	
1053	    // The residue really is this run's file: 32 bytes, mode 0600 -- it
1054	    // looks complete, yet it is not a saved key (the warning above is what
1055	    // keeps it from being mistaken for one). Nothing was stashed under
1056	    // another name.
1057	    let residue = fs::read(&key).expect("with unlink refused, this run's file remains");
1058	    assert_eq!(residue.len(), KEY_LEN);
1059	    assert_eq!(
1060	        residue, secret,
1061	        "the residue is exactly the key this failed run wrote"
1062	    );
1063	    assert_eq!(mode_of(&key), MODE_0600, "residue keeps mode 0600");
1064	
1065	    assert_sentinel_untouched(&sib, &sib_bytes, sib_mode);
1066	    assert_eq!(
1067	        mode_of(&tmp.path),
1068	        parent_before,
1069	        "parent directory permissions must never be loosened to force cleanup"
1070	    );
1071	
1072	    // Remove the residue manually (the user is told to); the scratch dir
1073	    // must not keep a key around.
1074	    fs::remove_file(&key).unwrap();
1075	}
