1077	fn close_eintr_boundary_saves_and_wipes_before_the_report(
1078	    sup: &Support,
1079	    bin: &Path,
1080	    profile: &str,
1081	) {
1082	    let tmp = Tmp::new(&format!("close-eintr-{profile}"));
1083	    let key = tmp.child("key");
1084	    let trace = tmp.child("trace.log");
1085	    fs::File::create(&trace).unwrap();
1086	    fs::set_permissions(&trace, fs::Permissions::from_mode(0o644)).unwrap();
1087	
1088	    // close() releases the descriptor but reports EINTR: an interruption,
1089	    // not a failure. The save succeeds and the temporary key is still wiped
1090	    // before the success report. From the observer's side the close syscall
1091	    // itself succeeds, so this runs under the success scenario.
1092	    let obs = observe(
1093	        &sup.observer,
1094	        bin,
1095	        "success",
1096	        &key,
1097	        &[sup.randtrap.clone(), sup.permfail.clone()],
1098	        &[
1099	            ("WRAPFILE_TEST_GETRANDOM_PARTIAL", "8"),
1100	            ("WRAPFILE_TEST_CLOSE_EINTR", "1"),
1101	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
1102	        ],
1103	        &trace,
1104	    );
1105	    if !observer_ran(&obs) {
1106	        return;
1107	    }
