122	#ifndef PTRACE_GET_SYSCALL_INFO
123	#define PTRACE_GET_SYSCALL_INFO 0x420e
124	#endif
125	#ifndef PTRACE_SYSCALL_INFO_NONE
126	#define PTRACE_SYSCALL_INFO_NONE 0
127	#define PTRACE_SYSCALL_INFO_ENTRY 1
128	#define PTRACE_SYSCALL_INFO_EXIT 2
