132	#if defined(__aarch64__)
133	#include <asm/ptrace.h>
134	typedef struct user_pt_regs gregs_t;
135	#define GREG_NT NT_PRSTATUS
136	static long greg_nr(const gregs_t *g) { return (long)g->regs[8]; }
137	static long greg_arg(const gregs_t *g, int i) { return (long)g->regs[i]; }
138	static long greg_ret(const gregs_t *g) { return (long)g->regs[0]; }
139	static unsigned long greg_pc(const gregs_t *g) { return g->pc; }
140	/* svc #imm: 1101 0100 000x xxxx xxxx xxxx xx00 0001 */
141	static int is_syscall_insn_word(uint32_t insn)
142	{
143	    return (insn & 0xffe0001fu) == 0xd4000001u;
144	}
145	#elif defined(__x86_64__)
146	#include <sys/user.h>
147	typedef struct user_regs_struct gregs_t;
148	#define GREG_NT NT_PRSTATUS
149	static long greg_nr(const gregs_t *g) { return (long)g->orig_rax; }
150	static long greg_arg(const gregs_t *g, int i)
151	{
152	    switch (i) {
153	    case 0: return (long)g->rdi;
154	    case 1: return (long)g->rsi;
155	    case 2: return (long)g->rdx;
156	    case 3: return (long)g->r10;
157	    case 4: return (long)g->r8;
158	    default: return (long)g->r9;
159	    }
160	}
161	static long greg_ret(const gregs_t *g) { return (long)g->rax; }
162	static unsigned long greg_pc(const gregs_t *g) { return g->rip; }
163	static int is_syscall_insn_word(uint32_t insn)
164	{
165	    /* Little-endian first two bytes of `syscall` (0f 05). */
166	    return (insn & 0xffffu) == 0x050fu;
167	}
168	#else
169	#error "keylife supports x86_64 and aarch64 only"
170	#endif
171	
172	/* write/writev/openat/close/getrandom/exit_group/rt_sigreturn numbers come
173	 * from <sys/syscall.h>, where they are per-architecture (e.g. exit_group is
174	 * 94 on arm64 and 231 on x86_64). */
175	#ifndef SYS_rt_sigreturn
176	#error "SYS_rt_sigreturn not defined for this architecture"
177	#endif
178	#define SYS_rt_sigreturn_local SYS_rt_sigreturn
179	
180	/* glibc's unlink() is unlinkat(AT_FDCWD, ...) on both supported arches. */
181	#ifndef SYS_unlinkat
182	#error "SYS_unlinkat not defined for this architecture"
183	#endif
184	
185	#define KEYN 32
186	
187	/* Upper bound on user instructions between the watch arm point and the
188	 * buffer being fully zero. The real wipe is a few hundred instructions at
189	 * -O0 and fewer at -O2; the bound only turns a missing wipe into a fast
190	 * FAIL instead of single-stepping all the way to process exit. */
191	#define WIPE_STEP_BUDGET 2000000L
192	
193	enum mode { MODE_SUCCESS, MODE_RANDFAIL, MODE_WRITEFAIL, MODE_CLOSEFAIL };
194	
195	struct observer {
196	    pid_t pid;
197	    enum mode mode;
198	
199	    uint64_t p;                 /* address of the guest's 32-byte buffer */
200	    int phase;                  /* 0 pre-fill, 1 filling, 2 filled,
201	                                   4 wipe watch armed, 5 wipe observed */
202	    int held;                   /* pattern prefix delivered so far */
203	    int sentinel;               /* sentinel bytes planted in undelivered tail */
204	    uint8_t secret[KEYN];       /* observed full key (once filled) */
205	    int keyfd;                  /* fd of the key file, or -1 */
206	    int abort_unlink_seen;      /* abort_save's unlink after a failed save */
207	    int output_after_wipe;
208	    int fill_req32_seen;
209	    int wipe_reported;
210	    long wipe_steps;
211	    int failed;
212	    char fail_reason[256];
213	
214	    /* pending syscall-entry state */
215	    int entry_valid;
216	    long entry_nr;
217	    uint64_t entry_a0, entry_a1, entry_a2;
218	};
219	
220	static void die_usage(void)
221	{
222	    fprintf(stderr,
223	        "usage: keylife <success|randfail|writefail|closefail> <stdout-cap>"
224	        " <stderr-cap> -- <guest> [args...]\n");
225	    exit(2);
226	}
227	
228	static void set_fail(struct observer *o, const char *fmt, ...)
229	{
230	    if (o->failed)
231	        return;
232	    va_list ap;
233	    va_start(ap, fmt);
234	    o->failed = 1;
235	    vsnprintf(o->fail_reason, sizeof o->fail_reason, fmt, ap);
236	    va_end(ap);
237	    printf("FAIL reason=%s\n", o->fail_reason);
238	    fflush(stdout);
239	}
240	
241	/* ---- remote memory ---- */
242	
243	static int remote_read(struct observer *o, uint64_t addr, void *buf, size_t n)
244	{
245	    struct iovec local = { buf, n };
246	    struct iovec remote = { (void *)addr, n };
247	    return process_vm_readv(o->pid, &local, 1, &remote, 1, 0) == (ssize_t)n
248	               ? 0
249	               : -1;
250	}
251	
252	static int remote_write(struct observer *o, uint64_t addr, const void *buf,
253	                        size_t n)
254	{
255	    struct iovec local = { (void *)buf, n };
256	    struct iovec remote = { (void *)addr, n };
257	    return process_vm_writev(o->pid, &local, 1, &remote, 1, 0) == (ssize_t)n
258	               ? 0
259	               : -1;
260	}
261	
262	static void get_gregs(struct observer *o, gregs_t *g)
263	{
264	    struct iovec iov = { g, sizeof *g };
265	    if (ptrace(PTRACE_GETREGSET, o->pid, (void *)GREG_NT, &iov) < 0)
266	        set_fail(o, "PTRACE_GETREGSET: %s", strerror(errno));
267	}
268	
269	static int read_keybuf(struct observer *o, uint8_t out[KEYN])
270	{
271	    memset(out, 0, KEYN);
272	    if (!o->p)
273	        return -1;
274	    return remote_read(o, o->p, out, KEYN);
275	}
276	
277	/* ---- the randtrap delivery pattern ---- */
278	
279	static uint8_t pattern_next(uint8_t b)
280	{
281	    return (uint8_t)(0x80 + (((unsigned)b - 0x80u + 1u) % 64u));
282	}
283	
284	/* Length of the contiguous non-zero pattern prefix the random source left:
285	 * starts with a 0x80..0xBF byte, every next byte advances by one modulo
286	 * the pattern period, and an undelivered slot is still zero. */
287	static int pattern_prefix(const uint8_t *buf)
288	{
289	    int i = 0;
290	    if (buf[0] < 0x80 || buf[0] >= 0xc0)
291	        return 0;
292	    while (i < KEYN && buf[i] != 0) {
293	        if (i > 0 && buf[i] != pattern_next(buf[i - 1]))
294	            break;
295	        i++;
296	    }
297	    return i;
298	}
299	
300	static int all_zero(const uint8_t *buf, int n)
301	{
302	    for (int i = 0; i < n; i++)
303	        if (buf[i])
304	            return 0;
305	    return 1;
306	}
307	
308	static void print_hex(const uint8_t *buf, int n)
309	{
310	    for (int i = 0; i < n; i++)
311	        printf("%02x", buf[i]);
312	}
313	
314	/* [P, P+32) must still equal the observed full key while the save borrows
315	 * it: a premature or partial wipe shows up here. */
316	static void require_still_holds_full_key(struct observer *o, const char *what,
317	                                         long fd)
318	{
319	    uint8_t cur[KEYN];
320	    if (read_keybuf(o, cur) != 0) {
321	        set_fail(o, "%s: cannot read key buffer", what);
322	        return;
323	    }
324	    if (memcmp(cur, o->secret, KEYN) != 0) {
325	        set_fail(o, "%s fd=%ld: key buffer changed before the save finished",
326	                 what, fd);
327	        return;
328	    }
329	    printf("EVENT name=%s fd=%ld held=%d\n", what, fd, KEYN);
330	    fflush(stdout);
331	}
332	
333	/* Classify the buffer after a getrandom completion of the key fill. */
334	static void refresh_fill(struct observer *o, long ret)
335	{
336	    uint8_t cur[KEYN];
337	    if (read_keybuf(o, cur) != 0) {
338	        set_fail(o, "cannot read key buffer after getrandom");
339	        return;
340	    }
341	    int pre = pattern_prefix(cur);
342	
343	    if (ret < 0) {
344	        if (o->mode != MODE_RANDFAIL) {
345	            set_fail(o,
346	                     "unexpected getrandom failure (ret=%ld) in mode %d",
347	                     ret, (int)o->mode);
348	            return;
349	        }
350	        if (pre <= 0 || pre >= KEYN) {
351	            set_fail(o,
352	                     "randfail scenario expected a partial delivery "
353	                     "(1..31 bytes), got prefix=%d ret=%ld",
354	                     pre, ret);
355	            return;
356	        }
357	        /* Plant a non-zero sentinel in the slots the source never
358	         * delivered: the product cannot read them on this error path, and
359	         * a full-buffer wipe must erase them as well. Bytes stay outside
360	         * the 0x80..0xBF pattern band so they cannot be mistaken for
361	         * random material. */
362	        uint8_t sent[KEYN];
363	        int m = KEYN - pre;
364	        for (int i = 0; i < m; i++)
365	            sent[i] =
366	                (uint8_t)(0xd0 + ((unsigned)(i * 5 + pre + 1) & 0x0f));
367	        if (remote_write(o, o->p + (uint64_t)pre, sent, (size_t)m) != 0) {
368	            set_fail(o, "cannot plant sentinel in undelivered tail");
369	            return;
370	        }
371	        o->held = pre;
372	        o->sentinel = m;
373	        memcpy(o->secret, cur, KEYN);
374	        o->phase = 4;
375	        o->wipe_steps = 0;
376	        printf("EVENT name=RANDOM_FAILED held=%d sentinel=%d\n", pre, m);
377	        fflush(stdout);
378	        return;
379	    }
380	
381	    o->held = pre;
382	    if (pre == KEYN) {
383	        memcpy(o->secret, cur, KEYN);
384	        o->phase = 2;
385	        printf("EVENT name=FILL_COMPLETE held=32 secret=");
386	        print_hex(cur, KEYN);
387	        putchar('\n');
388	        fflush(stdout);
389	    } else {
390	        o->phase = 1;
391	    }
392	}
393	
394	/* A completion of a getrandom that belongs to keygen's fill. `ret` is what
395	 * the guest observes (kernel return or the emulated SIGSYS value). */
396	static void on_getrandom_done(struct observer *o, long ret)
397	{
398	    if (!o->fill_req32_seen || o->phase >= 2 || o->phase == 4)
399	        return;
400	    refresh_fill(o, ret);
401	}
402	
403	/* ---- syscall-entry/exit handling (normal syscall-stop mode) ---- */
404	
405	static void on_syscall_entry(struct observer *o,
406	                             const struct ptrace_syscall_info *si)
407	{
408	    long nr = (long)si->entry.nr;
409	    o->entry_valid = 1;
410	    o->entry_nr = nr;
411	    o->entry_a0 = (uint64_t)si->entry.args[0];
412	    o->entry_a1 = (uint64_t)si->entry.args[1];
413	    o->entry_a2 = (uint64_t)si->entry.args[2];
414	
415	    if (nr == SYS_getrandom) {
416	        unsigned long len = (unsigned long)si->entry.args[1];
417	        /* The 32-byte request identifies keygen's own draw: the crate's
418	         * zero-length probe and the runtime startup draws use other
419	         * lengths, and the key fill is the process's first/final 32-byte
420	         * run. Once the key is filled a later unrelated 32-byte request
421	         * must never re-point P at a different buffer. */
422	        if (len == KEYN && !o->fill_req32_seen && o->phase < 2) {
423	            o->p = (uint64_t)si->entry.args[0];
424	            o->fill_req32_seen = 1;
425	            o->phase = 1;
426	            o->held = 0;
427	            o->sentinel = 0;
428	            o->wipe_reported = 0;
429	        }
430	        return;
431	    }
432	
433	    if (nr == SYS_write || nr == SYS_writev) {
434	        long fd = (long)si->entry.args[0];
435	        /* After the wipe the first stdout/stderr write confirms ordering. */
436	        if (o->phase == 5 && (fd == 1 || fd == 2)) {
437	            if (!o->output_after_wipe) {
438	                o->output_after_wipe = 1;
439	                printf("EVENT name=OUTPUT_AFTER_WIPE fd=%ld\n", fd);
440	                fflush(stdout);
441	            }
442	        }
443	
444	        /* Identify the key fd by *content*, not by "the first openat after
445	         * the fill": the product saves with plain write(2) of the key
446	         * buffer, so the first write whose offered bytes equal the key's
447	         * prefix can only target the key file. This stays correct even if
448	         * the runtime opens/writes something else between the fill and the
449	         * key file. Short writes advance the pointer, so only the first
450	         * offer (offset 0) is used for identification. */
451	        if (o->phase == 2 && o->keyfd < 0 &&
452	            !(fd == 1 || fd == 2)) {
453	            uint8_t offered[KEYN];
454	            size_t peek = (size_t)si->entry.args[2];
455	            if (peek > KEYN)
456	                peek = KEYN;
457	            if (peek >= 4 &&
458	                remote_read(o, (uint64_t)si->entry.args[1], offered,
459	                            peek) == 0 &&
460	                memcmp(offered, o->secret, peek) == 0) {
461	                o->keyfd = (int)fd;
462	            }
463	        }
464	
465	        /* Every offer of key bytes to the key fd must borrow the still-live
466	         * full key (checked at the buffer's own address, not the offer
467	         * pointer, so short writes with advancing pointers are covered). */
468	        if (o->phase >= 2 && o->keyfd >= 0 && fd == (long)o->keyfd)
469	            require_still_holds_full_key(o, "WRITE_BORROWS", fd);
470	    }
471	
472	    if (nr == SYS_unlinkat) {
473	        /* writefail mode: the failed save (the permfail shim makes the libc
474	         * write() return EIO without a syscall, so the failure itself is
475	         * not a syscall-exit event) reaches abort_save, whose first step is
476	         * unlinking this invocation's file. At that moment the complete key
477	         * must still be in the buffer: the wipe is only allowed afterwards,
478	         * on the way out of the operation. */
479	        if (o->mode == MODE_WRITEFAIL && o->phase == 2 &&
480	            o->keyfd >= 0 && !o->abort_unlink_seen) {
481	            require_still_holds_full_key(o, "WRITE_FAILED", (long)o->keyfd);
482	            if (!o->failed) {
483	                o->abort_unlink_seen = 1;
484	                printf("EVENT name=ABORT_UNLINK fd=%d held=%d\n", o->keyfd,
485	                       KEYN);
486	                fflush(stdout);
487	            }
488	        }
489	    }
490	}
491	
492	static void on_syscall_exit(struct observer *o,
493	                            const struct ptrace_syscall_info *si)
494	{
495	    long rval = (long)si->exit.rval;
496	    int iserr = si->exit.is_error;
497	
498	    if (!o->entry_valid)
499	        return;
500	
501	    switch (o->entry_nr) {
502	    case SYS_getrandom:
503	        on_getrandom_done(o, rval);
504	        break;
505	
506	    case SYS_openat:
507	        /* The key fd is identified by the content of the first key write
508	         * (see on_syscall_entry), not by fd number, so openat needs no
509	         * tracking here. */
510	        break;
511	
512	    case SYS_write:
513	    case SYS_writev:
514	        /* The write failure itself is injected inside libc by the permfail
515	         * shim (it returns EIO without issuing the syscall), so it is
516	         * recognized at abort_save's unlink entry, not here. */
517	        break;
518	
519	    case SYS_close:
520	        if (o->phase == 2 && o->keyfd >= 0 &&
521	            (long)o->entry_a0 == (long)o->keyfd && !iserr) {
522	            if (o->mode == MODE_SUCCESS || o->mode == MODE_CLOSEFAIL) {
523	                /* closefail: the close *syscall* succeeds -- the permfail
524	                 * shim reports the unrecoverable close error in user space
525	                 * afterwards, so this is also the failed-close arm point. */
526	                require_still_holds_full_key(o, "CLOSE_STILL_HELD",
527	                                            (long)o->keyfd);
528	            } else if (o->mode == MODE_WRITEFAIL && o->abort_unlink_seen) {
529	                /* abort_save unlinked first and now closes the still-open
530	                 * key fd; the full key must still be present at this point
531	                 * and wiped only afterwards, on the way out. */
532	                require_still_holds_full_key(o, "ABORT_CLOSE_STILL_HELD",
533	                                            (long)o->keyfd);
534	            }
535	            if (!o->failed &&
536	                ((o->mode == MODE_SUCCESS) || (o->mode == MODE_CLOSEFAIL) ||
537	                 (o->mode == MODE_WRITEFAIL && o->abort_unlink_seen))) {
538	                o->phase = 4;
539	                o->held = KEYN;
540	                o->sentinel = 0;
541	                o->wipe_steps = 0;
542	            }
543	        }
544	        break;
545	    }
546	
547	    o->entry_valid = 0;
548	}
549	
550	/* ---- SIGSYS (seccomp-emulated getrandom) handling ---- */
551	
552	/* The randtrap shim emulates a trapped getrandom inside a SIGSYS handler:
553	 * delivery stop -> handler runs (its own trace write) -> rt_sigreturn ->
554	 * the guest resumes after the svc with the emulated value in the return
555	 * register. Drive that sequence and hand the emulated result to the fill
556	 * tracker. Returns 0 normally, -1 once the guest is gone or a FAIL was
557	 * raised. */
558	static int drive_sigsys(struct observer *o)
559	{
560	    int status;
561	    int delivered = 0;
562	    for (;;) {
563	        /* Inject SIGSYS exactly once: re-injecting on every stop would
564	         * queue additional SIGSYSs behind the handler's blocked signal,
565	         * and sigreturn unblocking it would re-enter the handler forever. */
566	        if (ptrace(PTRACE_SYSCALL, o->pid, 0,
567	                   delivered ? 0 : (void *)(long)SIGSYS) < 0) {
568	            set_fail(o, "ptrace inject SIGSYS: %s", strerror(errno));
569	            return -1;
570	        }
571	        delivered = 1;
572	        if (waitpid(o->pid, &status, 0) < 0) {
573	            set_fail(o, "waitpid in SIGSYS: %s", strerror(errno));
574	            return -1;
575	        }
576	        if (WIFEXITED(status) || WIFSIGNALED(status))
577	            return -1;
578	        if (!WIFSTOPPED(status))
579	            continue;
580	        int sig = WSTOPSIG(status);
581	        if (sig == (SIGTRAP | 0x80)) {
582	            struct ptrace_syscall_info si;
583	            memset(&si, 0, sizeof si);
584	            if (ptrace(PTRACE_GET_SYSCALL_INFO, o->pid, sizeof si, &si) < 0)
585	                continue;
586	            if (si.op == PTRACE_SYSCALL_INFO_ENTRY &&
587	                (long)si.entry.nr == SYS_rt_sigreturn_local) {
588	                /* Run rt_sigreturn; on its exit the restored frame carries
589	                 * the emulated getrandom result. */
590	                if (ptrace(PTRACE_SYSCALL, o->pid, 0, 0) < 0)
591	                    return -1;
592	                if (waitpid(o->pid, &status, 0) < 0)
593	                    return -1;
594	                if (WIFEXITED(status) || WIFSIGNALED(status))
595	                    return -1;
596	                gregs_t g;
597	                get_gregs(o, &g);
598	                if (o->failed)
599	                    return -1;
600	                on_getrandom_done(o, greg_ret(&g));
601	                return o->failed ? -1 : 0;
602	            }
603	        } else if (sig == SIGSYS) {
604	            /* A second SIGSYS stop before the handler ran (nested trap
605	             * bookkeeping): it is already being delivered; resume with no
606	             * new injection. */
607	            delivered = 1;
608	            continue;
609	        }
610	    }
611	}
612	
613	/* ---- wipe watch (single-step mode) ---- */
614	
615	/* If the guest is stopped immediately before a write/exit_group syscall
616	 * (entry syscall-stop, or a single-step trap on the syscall instruction),
617	 * return its number and fd argument; otherwise -1. */
618	static long pending_syscall(struct observer *o, int sig,
619	                            const struct ptrace_syscall_info *si,
620	                            const gregs_t *g, long *fd_out)
621	{
622	    if (sig == (SIGTRAP | 0x80) && si->op == PTRACE_SYSCALL_INFO_ENTRY) {
623	        long nr = (long)si->entry.nr;
624	        *fd_out = (long)si->entry.args[0];
625	        return nr;
626	    }
627	    if (sig == SIGTRAP) {
628	        unsigned long pc = greg_pc(g);
629	        uint32_t insn = 0;
630	        if (remote_read(o, pc, &insn, sizeof insn) == 0 &&
631	            is_syscall_insn_word(insn)) {
632	            long nr = greg_nr(g);
633	            *fd_out = greg_arg(g, 0);
634	            return nr;
635	        }
636	    }
637	    return -1;
638	}
639	
640	/* One single-step observation. Returns 1 while the watch stays armed. */
641	static int watch_step(struct observer *o, int sig,
642	                      const struct ptrace_syscall_info *si, const gregs_t *g)
643	{
644	    o->wipe_steps++;
645	    if (o->wipe_steps > WIPE_STEP_BUDGET) {
646	        set_fail(o,
647	                 "key buffer was not zeroed within %ld user instructions",
648	                 WIPE_STEP_BUDGET);
649	        return 0;
650	    }
651	
652	    uint8_t cur[KEYN];
653	    if (read_keybuf(o, cur) != 0) {
654	        set_fail(o, "cannot read key buffer while wipe-watching");
655	        return 0;
656	    }
657	
658	    long fd = -1;
659	    long nr = pending_syscall(o, sig, si, g, &fd);
660	
661	    /* closefail: after the failed close the save reaches abort_save, whose
662	     * first step is unlinking this invocation's file. At that moment the
663	     * complete key must still be in the buffer: the wipe is only allowed
664	     * afterwards, on the way out of the operation. (When the shim refuses
665	     * the unlink in user space no unlinkat syscall happens at all, so this
666	     * event is simply absent from that run.) */
667	    if (o->mode == MODE_CLOSEFAIL && nr == SYS_unlinkat &&
668	        !o->abort_unlink_seen) {
669	        if (memcmp(cur, o->secret, KEYN) != 0) {
670	            set_fail(o,
671	                     "abort unlink: key buffer changed before the save "
672	                     "finished");
673	            return 0;
674	        }
675	        o->abort_unlink_seen = 1;
676	        printf("EVENT name=ABORT_UNLINK fd=%d held=%d\n", o->keyfd, KEYN);
677	        fflush(stdout);
678	    }
679	
680	    if ((nr == SYS_write || nr == SYS_writev) && (fd == 1 || fd == 2)) {
681	        if (!all_zero(cur, KEYN)) {
682	            set_fail(o,
683	                     "guest performed fd %ld output before the key buffer "
684	                     "was zeroed (held=%d sentinel=%d, step %ld)",
685	                     fd, o->held, o->sentinel, o->wipe_steps);
686	            return 0;
687	        }
688	        if (!o->output_after_wipe) {
689	            o->output_after_wipe = 1;
690	            printf("EVENT name=OUTPUT_AFTER_WIPE fd=%ld\n", fd);
691	            fflush(stdout);
692	        }
693	    }
694	    if (nr == SYS_exit_group && !all_zero(cur, KEYN)) {
695	        set_fail(o,
696	                 "guest reached exit_group with the key buffer not zeroed "
697	                 "(held=%d sentinel=%d)",
698	                 o->held, o->sentinel);
699	        return 0;
700	    }
701	
702	    if (!o->wipe_reported && all_zero(cur, KEYN)) {
703	        o->wipe_reported = 1;
704	        o->phase = 5;
705	        printf("EVENT name=WIPED held=%d sentinel=%d steps=%ld\n", o->held,
706	               o->sentinel, o->wipe_steps);
707	        fflush(stdout);
708	        return 0;
709	    }
710	    return 1;
711	}
712	
713	/* ---- child ---- */
714	
715	static void run_child(char **argv, const char *out_cap, const char *err_cap)
716	{
717	    int outfd = open(out_cap, O_WRONLY | O_CREAT | O_TRUNC, 0600);
718	    if (outfd < 0)
719	        _exit(126);
720	    int errfd = open(err_cap, O_WRONLY | O_CREAT | O_TRUNC, 0600);
721	    if (errfd < 0)
722	        _exit(126);
723	    dup2(outfd, STDOUT_FILENO);
724	    dup2(errfd, STDERR_FILENO);
725	    if (outfd > STDERR_FILENO)
726	        close(outfd);
727	    if (errfd > STDERR_FILENO)
728	        close(errfd);
729	
730	    ptrace(PTRACE_TRACEME, 0, 0, 0);
731	    raise(SIGSTOP);
732	    execv(argv[0], argv);
733	    _exit(127);
734	}
735	
736	int main(int argc, char **argv)
737	{
738	    if (argc < 6)
739	        die_usage();
740	    enum mode mode;
741	    if (!strcmp(argv[1], "success"))
742	        mode = MODE_SUCCESS;
743	    else if (!strcmp(argv[1], "randfail"))
744	        mode = MODE_RANDFAIL;
745	    else if (!strcmp(argv[1], "writefail"))
746	        mode = MODE_WRITEFAIL;
747	    else if (!strcmp(argv[1], "closefail"))
748	        mode = MODE_CLOSEFAIL;
749	    else
750	        die_usage();
751	    const char *out_cap = argv[2];
752	    const char *err_cap = argv[3];
753	    if (strcmp(argv[4], "--") != 0)
754	        die_usage();
755	    char **guest_argv = &argv[5];
756	
757	    struct observer o;
758	    memset(&o, 0, sizeof o);
759	    o.mode = mode;
760	    o.keyfd = -1;
761	
762	    pid_t pid = fork();
763	    if (pid < 0) {
764	        perror("fork");
765	        return 2;
766	    }
767	    if (pid == 0)
768	        run_child(guest_argv, out_cap, err_cap);
769	    o.pid = pid;
770	
771	    int status;
772	    if (waitpid(pid, &status, WUNTRACED) < 0) {
773	        perror("waitpid initial");
774	        kill(pid, SIGKILL);
775	        waitpid(pid, &status, 0);
776	        return 2;
777	    }
778	    if (WIFEXITED(status) || WIFSIGNALED(status)) {
779	        fprintf(stderr, "guest exited before tracing could start\n");
780	        return 2;
781	    }
782	    /* TRACEEXEC makes the post-exec stop a proper PTRACE_EVENT stop (plain
783	     * SIGTRAP with the event marker in the wait status) instead of a legacy
784	     * SIGTRAP that looks like a signal to deliver -- delivering that would
785	     * kill the guest at the very first stop. */
786	    if (ptrace(PTRACE_SETOPTIONS, pid, 0,
787	               (void *)(long)(PTRACE_O_TRACESYSGOOD | PTRACE_O_TRACEEXEC)) < 0) {
788	        fprintf(stderr, "PTRACE_SETOPTIONS: %s\n", strerror(errno));
789	        kill(pid, SIGKILL);
790	        waitpid(pid, &status, 0);
791	        return 2;
792	    }
793	
794	    int stepping = 0;
795	    int guest_rc = -1;
796	    int inject_sig = 0;
797	    for (;;) {
798	        long request = stepping ? PTRACE_SINGLESTEP : PTRACE_SYSCALL;
799	        if (ptrace(request, pid, 0,
800	                   inject_sig ? (void *)(long)inject_sig : 0) < 0) {
801	            if (errno == ESRCH)
802	                break;
803	            set_fail(&o, "ptrace continue: %s", strerror(errno));
804	            break;
805	        }
806	        inject_sig = 0;
807	        if (waitpid(pid, &status, 0) < 0) {
808	            set_fail(&o, "waitpid: %s", strerror(errno));
809	            break;
810	        }
811	        if (WIFEXITED(status)) {
812	            guest_rc = WEXITSTATUS(status);
813	            printf("EVENT name=GUEST_EXIT rc=%d\n", guest_rc);
814	            fflush(stdout);
815	            break;
816	        }
817	        if (WIFSIGNALED(status)) {
818	            set_fail(&o, "guest killed by signal %d", WTERMSIG(status));
819	            break;
820	        }
821	        if (!WIFSTOPPED(status)) {
822	            set_fail(&o, "unexpected wait status 0x%x", status);
823	            break;
824	        }
825	        int sig = WSTOPSIG(status);
826	        unsigned int event = (unsigned int)((unsigned)status >> 16);
827	
828	        /* A seccomp-trapped getrandom has no ordinary entry/exit pair:
829	         * drive the SIGSYS handler before doing anything else. */
830	        if (sig == SIGSYS) {
831	            if (drive_sigsys(&o) < 0)
832	                break;
833	            if (o.phase == 4 && !o.failed)
834	                stepping = 1;
835	            continue;
836	        }
837	
838	        /* PTRACE_EVENT stops (e.g. PTRACE_EVENT_EXEC after the child's
839	         * execve) are bookkeeping, not signals: continue silently. */
840	        if (sig == SIGTRAP && event != 0)
841	            continue;
842	
843	        gregs_t g;
844	        struct ptrace_syscall_info si;
845	        memset(&si, 0, sizeof si);
846	        if (sig == (SIGTRAP | 0x80))
847	            (void)ptrace(PTRACE_GET_SYSCALL_INFO, pid, sizeof si, &si);
848	        get_gregs(&o, &g);
849	        if (o.failed)
850	            break;
851	
852	        if (stepping) {
853	            /* Inside the watch window a plain SIGTRAP (no event marker, no
854	             * syscall-good bit) is the single-step trap; a syscall-good
855	             * stop is stepping over a syscall instruction. Anything else is
856	             * a genuine signal to reinject. */
857	            if (sig != SIGTRAP && sig != (SIGTRAP | 0x80)) {
858	                inject_sig = sig;
859	                continue;
860	            }
861	            if (!watch_step(&o, sig, &si, &g))
862	                stepping = 0;
863	            continue;
864	        }
865	
866	        if (sig != (SIGTRAP | 0x80)) {
867	            /* Genuine signal: deliver it to the guest and keep tracing. */
868	            inject_sig = sig;
869	            continue;
870	        }
871	
872	        if (si.op == PTRACE_SYSCALL_INFO_ENTRY)
873	            on_syscall_entry(&o, &si);
874	        else if (si.op == PTRACE_SYSCALL_INFO_EXIT)
875	            on_syscall_exit(&o, &si);
876	        if (o.failed)
877	            break;
878	        if (o.phase == 4)
879	            stepping = 1;
880	    }
881	
882	    if (!o.failed) {
883	        if (o.phase != 5) {
884	            set_fail(&o,
885	                     "wipe was never observed (phase=%d held=%d sentinel=%d)",
886	                     o.phase, o.held, o.sentinel);
887	        } else if (!o.output_after_wipe) {
888	            set_fail(&o,
889	                     "buffer was wiped but the program then made no "
890	                     "stdout/stderr write to confirm ordering");
891	        } else if (mode == MODE_SUCCESS && o.keyfd < 0) {
892	            set_fail(&o, "success path never opened the key file");
893	        } else if (mode == MODE_RANDFAIL && o.sentinel == 0) {
894	            set_fail(&o, "randfail path never planted the tail sentinel");
895	        } else if (mode == MODE_WRITEFAIL && o.keyfd < 0) {
896	            set_fail(&o, "writefail path never opened the key file");
897	        } else if (mode == MODE_CLOSEFAIL && o.keyfd < 0) {
898	            set_fail(&o, "closefail path never opened the key file");
899	        }
900	    }
901	
902	    if (o.failed) {
903	        kill(pid, SIGKILL);
904	        waitpid(pid, &status, 0);
905	    }
906	
907	    (void)guest_rc;
908	    return o.failed ? 1 : 0;
909	}
