1	//! Regression coverage for the keygen file-permission contract on Unix.
2	//!
3	//! What is protected here (see README "文件权限"):
4	//!
5	//! * Under umask 0022 / 0000 / 0777 a key is generated successfully only as
6	//!   exactly 32 raw bytes with final mode exactly 0600 -- owner read+write,
7	//!   no group/other bits, no extra bits; 0400/0200/0000 are not success.
8	//! * The file is never group/other-accessible, not even for an instant: the
9	//!   mode observed right after creation already carries no group/other bits.
10	//! * Permissions are both set to and *confirmed* as exactly 0600 before any
11	//!   key byte is written. This cannot be observed from the final file, so a
12	//!   small LD_PRELOAD shim (tests/support/permfail) traces the program's
13	//!   open/fchmod/fstat/write calls from inside the process.
14	//! * If the filesystem rejects the required mode (fchmod fails) or the mode
15	//!   cannot be confirmed (fstat fails or reports something other than 0600),
16	//!   keygen exits 1, reports the permission problem on stderr, prints no
17	//!   success message, writes no key bytes, and removes the partial file --
18	//!   without touching pre-existing files, directories, symlinks, or the
19	//!   parent directory. If the system also refuses to remove this run's
20	//!   file, stderr keeps the permission problem, reports the failed cleanup,
21	//!   and warns that this run's file may still be present at the target.
22	//! * Existing CLI behaviour (--version, usage/exit code 2) is unchanged.
23	#![cfg(unix)]
24	
25	mod common;
26	
27	use std::collections::HashMap;
28	use std::fs;
29	use std::os::unix::fs::{MetadataExt, PermissionsExt};
30	use std::path::{Path, PathBuf};
31	use std::process::Command;
32	use std::sync::atomic::{AtomicU64, Ordering};
33	
34	const KEY_LEN: usize = 32;
35	const MODE_0600: u32 = 0o600;
36	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
37	
38	fn bin() -> PathBuf {
39	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
40	}
41	
42	fn permfail_so() -> Option<PathBuf> {
43	    common::permfail_so()
44	}
45	
46	// ---------------------------------------------------------------------------
47	// scratch directory
48	// ---------------------------------------------------------------------------
49	
50	struct Tmp {
51	    path: PathBuf,
52	}
53	
54	impl Tmp {
55	    fn new(label: &str) -> Tmp {
56	        static SEQ: AtomicU64 = AtomicU64::new(0);
57	        let path = std::env::temp_dir().join(format!(
58	            "wrapfile-keygen-tests-{}-{}-{}",
59	            std::process::id(),
60	            label,
61	            SEQ.fetch_add(1, Ordering::Relaxed)
62	        ));
63	        fs::create_dir_all(&path).unwrap();
64	        // Don't let the harness process's own (possibly strict) umask decide
65	        // the scratch dir's mode: keygen needs a writable parent, and every
66	        // test sets the umask it cares about inside the child shell.
67	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
68	        Tmp { path }
69	    }
70	
71	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
72	        self.path.join(name)
73	    }
74	}
75	
76	impl Drop for Tmp {
77	    fn drop(&mut self) {
78	        // A read-only-parent test may have stripped write permission;
79	        // restore it so teardown can remove the tree.
80	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
81	        let _ = fs::remove_dir_all(&self.path);
82	    }
83	}
84	
85	// ---------------------------------------------------------------------------
86	// running the binary
87	// ---------------------------------------------------------------------------
88	
89	struct Run {
90	    rc: i32,
91	    out: Vec<u8>,
92	    err: Vec<u8>,
93	}
94	
95	fn run_version() -> Run {
96	    let o = Command::new(bin()).arg("--version").output().unwrap();
97	    Run {
98	        rc: o.status.code().unwrap_or(-1),
99	        out: o.stdout,
100	        err: o.stderr,
101	    }
102	}
103	
104	fn run_args(args: &[&str]) -> Run {
105	    let o = Command::new(bin()).args(args).output().unwrap();
106	    Run {
107	        rc: o.status.code().unwrap_or(-1),
108	        out: o.stdout,
109	        err: o.stderr,
110	    }
111	}
112	
113	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
114	/// wrapper (`umask MMMM; exec "$@"`), optionally with the permfail shim
115	/// preloaded and a trace file configured.
116	fn run_keygen(
117	    key: &Path,
118	    umask: u32,
119	    preload_so: Option<&Path>,
120	    extra_env: &[(&str, &str)],
121	    trace_file: Option<&Path>,
122	) -> Run {
123	    let mut cmd = Command::new("/bin/sh");
124	    cmd.arg("-c")
125	        .arg(format!("umask {umask:04o}; exec \"$@\""))
126	        .arg("sh")
127	        .arg(bin())
128	        .arg("keygen")
129	        .arg(key);
130	
131	    if let Some(so) = preload_so {
132	        cmd.env("LD_PRELOAD", so);
133	    }
134	    for (k, v) in extra_env {
135	        cmd.env(k, v);
136	    }
137	    if let Some(t) = trace_file {
138	        cmd.env("WRAPFILE_TEST_TRACE_FILE", t);
139	    }
140	
141	    let o = cmd.output().unwrap();
142	    Run {
143	        rc: o.status.code().unwrap_or(-1),
144	        out: o.stdout,
145	        err: o.stderr,
146	    }
147	}
148	
149	// ---------------------------------------------------------------------------
150	// shim trace log
151	// ---------------------------------------------------------------------------
152	
153	struct Event {
154	    kind: String,
155	    attrs: HashMap<String, String>,
156	    index: usize,
157	}
158	
159	impl Event {
160	    fn get(&self, key: &str) -> Option<&str> {
161	        self.attrs.get(key).map(String::as_str)
162	    }
163	
164	    fn mode(&self) -> Option<u32> {
165	        self.get("mode").and_then(|v| u32::from_str_radix(v, 8).ok())
166	    }
167	
168	    fn size(&self) -> Option<u64> {
169	        self.get("size").and_then(|v| v.parse().ok())
170	    }
171	
172	    fn ret(&self) -> Option<i32> {
173	        self.get("ret").and_then(|v| v.parse().ok())
174	    }
175	}
176	
177	fn parse_trace(path: &Path) -> Vec<Event> {
178	    let text = fs::read_to_string(path).unwrap();
179	    text.lines()
180	        .enumerate()
181	        .map(|(index, line)| {
182	            let mut it = line.split_whitespace();
183	            let kind = it.next().unwrap_or("").to_string();
184	            let attrs = it
185	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
186	                .collect();
187	            Event { kind, attrs, index }
188	        })
189	        .collect()
190	}
191	
192	fn first_index(events: &[Event], pred: impl Fn(&Event) -> bool) -> Option<usize> {
193	    events.iter().position(pred)
194	}
195	
196	/// Create the trace file up front (mode 0644) so that it stays readable even
197	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
198	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
199	    let p = dir.join(name);
200	    fs::File::create(&p).unwrap();
201	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
202	    p
203	}
204	
205	// ---------------------------------------------------------------------------
206	// filesystem assertions
207	// ---------------------------------------------------------------------------
208	
209	fn mode_of(path: &Path) -> u32 {
210	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
211	}
212	
213	fn assert_key_file_ok(path: &Path, run: &Run) -> Vec<u8> {
214	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
215	    assert!(run.err.is_empty(), "unexpected stderr: {}", String::from_utf8_lossy(&run.err));
216	
217	    let meta = fs::metadata(path).expect("key file should exist on success");
218	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
219	
220	    let mode = meta.mode() & 0o7777;
221	    // One assertion that carries the whole contract: exactly 0600 -- owner
222	    // r+w both present, all group/other bits off, no setuid/setgid/sticky.
223	    assert_eq!(
224	        mode, MODE_0600,
225	        "key file mode must be exactly 0600 (owner rw only), got {mode:04o}"
226	    );
227	
228	    let expected_stdout =
229	        format!("Key saved to {}\n", path.display()).into_bytes();
230	    assert_eq!(run.out, expected_stdout, "stdout should only announce the save location");
231	
232	    let bytes = fs::read(path).unwrap();
233	    assert_eq!(bytes.len(), KEY_LEN);
234	    assert!(
235	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
236	        "key bytes must never appear on stdout/stderr"
237	    );
238	    bytes
239	}
240	
241	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
242	    needle.is_empty()
243	        || haystack
244	            .windows(needle.len())
245	            .any(|w| w == needle)
246	}
247	
248	fn assert_permission_failure_cleaned(path: &Path, run: &Run, dir: &Path, allowed_entries: &[&str]) {
249	    assert_eq!(run.rc, 1, "permission problems must fail with exit code 1");
250	    assert!(run.out.is_empty(), "no success message on failure, got {}", String::from_utf8_lossy(&run.out));
251	    assert!(!run.err.is_empty(), "stderr must explain the failure");
252	    let stderr = String::from_utf8_lossy(&run.err);
253	    assert!(
254	        stderr.contains("0600") || stderr.to_lowercase().contains("permission"),
255	        "stderr must describe the permission problem, got: {stderr}"
256	    );
257	    assert!(!path.exists(), "the failed generation's target must be removed");
258	
259	    // Nothing else left behind in the parent directory.
260	    let mut leftovers: Vec<String> = fs::read_dir(dir)
261	        .unwrap()
262	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
263	        .filter(|n| !allowed_entries.contains(&n.as_str()))
264	        .collect();
265	    leftovers.sort();
266	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
267	}
268	
269	// A pre-existing object that must survive a failed keygen byte-for-byte.
270	struct Sentinel {
271	    path: PathBuf,
272	    bytes: Vec<u8>,
273	    mode: u32,
274	    inode: u64,
275	}
276	
277	impl Sentinel {
278	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
279	        let path = dir.join(name);
280	        fs::write(&path, bytes).unwrap();
281	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
282	        let meta = fs::metadata(&path).unwrap();
283	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
284	    }
285	
286	    fn assert_untouched(&self) {
287	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
288	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
289	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
290	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
291	    }
292	}
293	
294	// ---------------------------------------------------------------------------
295	// tests
296	// ---------------------------------------------------------------------------
297	
298	#[test]
299	fn succeeds_with_exactly_0600_under_all_umasks() {
300	    let so = permfail_so();
301	    let mut keys: Vec<Vec<u8>> = Vec::new();
302	
303	    for umask in UMASKS {
304	        let tmp = Tmp::new("success");
305	        let key = tmp.child(format!("key-{umask:04o}"));
306	        let trace = prepare_trace(&tmp.path, "trace.log");
307	
308	        let run = run_keygen(&key, umask, so.as_deref(), &[], Some(&trace));
309	        let bytes = assert_key_file_ok(&key, &run);
310	        keys.push(bytes);
311	
312	        if let Some(events) = so.as_ref().map(|_| parse_trace(&trace)) {
313	            // The descriptor the program created was never group/other
314	            // accessible, not even at birth. Under umask 0777 the owner
315	            // bits are also stripped at birth (0000) and repaired later.
316	            let born = events.iter().find(|e| e.kind == "BORN").expect("BORN event");
317	            assert_eq!(born.mode().unwrap() & 0o077, 0, "group/other bits must be off from creation");
318	            let expected_born = if umask == 0o777 { 0o000 } else { 0o600 };
319	            assert_eq!(born.mode().unwrap(), expected_born,
320	                "umask {umask:04o} should yield birth mode {expected_born:04o}");
321	        }
322	    }
323	
324	    // Distinct runs draw independent random keys; none is the zero key.
325	    for k in &keys {
326	        assert!(k.iter().any(|&b| b != 0), "key must not be all zeroes");
327	    }
328	    assert_ne!(keys[0], keys[1]);
329	    assert_ne!(keys[1], keys[2]);
330	    assert_ne!(keys[0], keys[2]);
331	}
332	
333	#[test]
334	fn permissions_set_and_confirmed_before_any_key_byte() {
335	    let Some(so) = permfail_so() else {
336	        eprintln!("skipping: permfail shim not available on this target");
337	        return;
338	    };
339	
340	    for umask in UMASKS {
341	        let tmp = Tmp::new("before-write");
342	        let key = tmp.child("key");
343	        let trace = prepare_trace(&tmp.path, "trace.log");
344	
345	        let run = run_keygen(&key, umask, Some(&so), &[], Some(&trace));
346	        assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
347	        let events = parse_trace(&trace);
348	
349	        let first_write = first_index(&events, |e| e.kind == "FIRST_WRITE")
350	            .expect("the key must eventually be written");
351	        let w = &events[first_write];
352	
353	        // Immediately before the first write call: mode is exactly 0600 and
354	        // size is still 0 -- no key byte preceded the confirmation.
355	        assert_eq!(w.mode().unwrap(), MODE_0600,
356	            "mode at first write must be exactly 0600 (umask {umask:04o})");
357	        assert_eq!(w.size().unwrap(), 0,
358	            "file must be empty when 0600 is confirmed (umask {umask:04o})");
359	
360	        // fchmod set 0600 and an fstat confirmed it, both before the write.
361	        let chmod = first_index(&events, |e| {
362	            e.kind == "FCHMOD" && e.ret() == Some(0) && e.mode() == Some(MODE_0600)
363	        }).expect("fchmod(fd, 0600) must succeed");
364	        let confirm = first_index(&events, |e| {
365	            e.kind == "FSTAT"
366	                && e.ret() == Some(0)
367	                && e.mode() == Some(MODE_0600)
368	                && e.size() == Some(0)
369	        }).expect("an fstat must confirm exactly 0600 on an empty file");
370	        assert!(chmod < first_write, "fchmod must precede the first write");
371	        assert!(confirm < first_write, "confirmation must precede the first write");
372	
373	        // Every mode observation before the first write (birth included)
374	        // carries no group or other bits: the secret is never exposed while
375	        // open, even for an instant.
376	        for e in events.iter().take(first_write) {
377	            if e.kind == "BORN" || e.kind == "FSTAT" {
378	                if let Some(m) = e.mode() {
379	                    assert_eq!(m & 0o077, 0,
380	                        "group/other bits observed before write in event {}: {:04o}", e.index, m);
381	                }
382	            }
383	        }
384	
385	        // Final on-disk state matches what the trace promised.
386	        assert_eq!(mode_of(&key), MODE_0600);
387	        assert_eq!(fs::metadata(&key).unwrap().len() as usize, KEY_LEN);
388	    }
389	}
