1	/*
2	 * randtrap.c -- LD_PRELOAD shim for wrapfile keygen random-source tests.
3	 *
4	 * The getrandom crate used by wrapfile issues the getrandom(2) syscall with
5	 * inline assembly, so symbol interposition (as in the permfail shim) cannot
6	 * see it. This shim instead installs a seccomp filter (SECCOMP_RET_TRAP)
7	 * for getrandom inside the guest process and emulates the syscall in a
8	 * SIGSYS handler, letting the tests make the OS random source fail in
9	 * controlled ways on a machine where it works fine. The filter only traps
10	 * getrandom inside the fault-configured guest: every other syscall and
11	 * every other process -- including other wrapfile invocations -- keeps
12	 * using the real random source.
13	 *
14	 * Activation: only inside an executable whose basename starts with
15	 * "wrapfile" (checked via /proc/self/exe), and only when one of the fault
16	 * variables below is set. Everything is configured through the environment:
17	 *
18	 *   WRAPFILE_TEST_GETRANDOM_FAIL=1        every getrandom call fails with
19	 *                                         EIO before a single byte is drawn
20	 *   WRAPFILE_TEST_GETRANDOM_FAIL_AFTER=N  calls succeed until N bytes in
21	 *                                         total have been handed out (the
22	 *                                         first call is truncated to N if
23	 *                                         needed), then fail with EIO -- a
24	 *                                         source that dries up mid-key
25	 *   WRAPFILE_TEST_GETRANDOM_PARTIAL=N     every call returns at most N
26	 *                                         bytes but always succeeds -- a
27	 *                                         source that only ever delivers
28	 *                                         short reads (NOT a failure: the
29	 *                                         guest must keep drawing)
30	 *   WRAPFILE_TEST_TRACE_FILE=PATH         one GETRANDOM line per trapped
31	 *                                         call is appended here, plus a
32	 *                                         TRAP line when the shim arms
33	 *
34	 * Bytes handed to the guest follow a fixed, recognisable pattern that is
35	 * never valid text (0x80, 0x81, ... by global draw index), so the tests can
36	 * prove that on success the key file holds exactly the bytes the source
37	 * delivered -- nothing invented, nothing zero-padded -- and that on failure
38	 * those bytes leak nowhere: not on stdout/stderr in raw or hex form, and
39	 * not into any file left behind.
40	 *
41	 * The constructor records "TRAP armed" / "TRAP unavailable ..." in the
42	 * trace file so tests can skip cleanly on kernels without seccomp.
43	 */
