164	 * Called from the SIGSYS handler, so it only uses a stack buffer and the
165	 * raw write syscall. */
166	static void trace_getrandom(size_t req, unsigned long long base, long ret)
167	{
168	    char line[96];
169	    size_t n = 0;
170	    const char *p;
171	
172	    if (trace_fd < 0)
173	        return;
174	
175	    for (p = "GETRANDOM req="; *p; p++)
176	        line[n++] = *p;
