178	    for (p = " base="; *p; p++)
179	        line[n++] = *p;
180	    n += fmt_u64(line + n, base);
181	    for (p = " ret="; *p; p++)
182	        line[n++] = *p;
183	    if (ret < 0) {
184	        for (p = "-1 errno=EIO"; *p; p++)
185	            line[n++] = *p;
186	    } else {
